  (function() {
    // 1. Grab the raw data from the triggered row
   let rawData = Tabela_sklopov.selectedRow?.authors_data;

    if (!rawData) return "ERROR: authors_data is empty or undefined.";

    // 2. If PostgreSQL sent it as a string, parse it
    if (typeof rawData === 'string') {
      try {
        rawData = JSON.parse(rawData);
      } catch (e) {
        return "ERROR: Could not parse authors_data JSON.";
      }
    }

    if (!Array.isArray(rawData)) return "ERROR: authors_data is not an array. It is: " + typeof rawData;

    // 3. Try to find the primary author
    // Checking for true, 'true', 't', or 1 just in case Postgres formatted it weirdly
    const primary = rawData.find(a => 
      a.is_primary === true || 
      a.is_primary === 'true' || 
      a.is_primary === 't' || 
      a.is_primary === 1
    );

    // 4. Output the result
    if (primary) {
      return "SUCCESS: Primary Author is " + primary.name + " (ID: " + primary.id + ")";
    } else {
      // If it fails, print the raw data so we can see EXACTLY what 'is_primary' looks like
      return "NO PRIMARY FOUND. Here is the raw data: " + JSON.stringify(rawData);
    }
  })() 
}}
